from src.data_loading import buildTrainingTablefrom xgboost import XGBClassifierimport pandas as pdimport numpy as np from sklearn.metrics import matthews_corrcoeffrom sklearn.metrics import roc_auc_score"""STEPS1) SEPARATE INDEPENDENT VARIABLES X FROM DEPENDENT VARIABLE Y2) MAKE Y BINARY (BUY/NO BUY) FORWARD RETURN3) INITIALIZE AND FIT THE MODEL"""### DRY RUN##1# Make example dataexample_train, example_test = buildTrainingTable(['AAPL',                                                  'MMM'],                                                 '2020-01-01',                                                 '2023-01-10')example_train = example_train.dropna()example_test= example_test.dropna()# Separte x and Y# should these variables be scaled? If its non parametric I guess no?example_train_X = example_train[['Daily Return',                                'Momentum_,5',                                'Momentum_,20',                                'Momentum_,60',                                'Momentum_,120',                                'Volume,20',                                'Price_Level_High_252',                                'Price_Level_Low_252',                                'Relative Strength,20'                                ]]example_train_Y = example_train[['Forward Return_,20']]### here is evidence of poor naming conventions for my function, also this## should be a loopexample_test_X = example_test[['Daily Return',                                'Momentum_,5',                                'Momentum_,20',                                'Momentum_,60',                                'Momentum_,120',                                'Volume,20',                                'Price_Level_High_252',                                'Price_Level_Low_252',                                'Relative Strength,20'                                ]]example_test_Y = example_test[['Forward Return_,20']]##2#visialize the distributionexample_train_Y.hist()np.percentile(example_train_Y.dropna(),95)# 0.141, lets use that as our binary labelcutoff = np.percentile(example_train_Y.dropna(),95)#arbitrary cutoff to binarize labelexample_train_Y_binary = np.where(example_train_Y>cutoff, 1, 0)example_test_Y_binary = np.where(example_test_Y>cutoff, 1, 0)### initialize modelmodel = XGBClassifier(n_estimators=100, max_depth=3, learning_rate=0.1)#trainmodel.fit(example_train_X, example_train_Y_binary)#testpredict_binary = model.predict(example_test_X)predict_proba = model.predict_proba(example_test_X)#MCCmatthews_corrcoef(predict_binary, example_test_Y_binary)## 0.42572989357819624auc = roc_auc_score(example_test_Y_binary, predict_proba[:,1])#0.916